package com.metaverse.coin.strategy.core.arbitrage.multi;
import java.math.BigDecimal; import java.time.Duration; import java.time.Instant; import java.util.*;
public class CrossExchangeOpportunityScanService {
 private final List<CrossExchangeMarketDataProvider> providers; private final CrossExchangeOpportunitySelector selector;
 private final CrossExchangeOpportunityStabilityGate gate; private final CrossExchangeOpportunitySelector.Limits limits;
 private final Map<Exchange,ExchangeCost> costs; private final BigDecimal targetNotional;
 private final ExchangeHealthRegistry health;
 private final PerpetualContractCatalog catalog;
 private final Map<String,CrossExchangeOpportunity> approved=new java.util.concurrent.ConcurrentHashMap<>();
 private volatile List<CrossExchangeOpportunity> lastEvaluated=List.of();
 public CrossExchangeOpportunityScanService(List<CrossExchangeMarketDataProvider> p,CrossExchangeOpportunitySelector s,CrossExchangeOpportunityStabilityGate g,CrossExchangeOpportunitySelector.Limits l,Map<Exchange,ExchangeCost> c,BigDecimal n,ExchangeHealthRegistry h){this(p,s,g,l,c,n,h,null);}
 public CrossExchangeOpportunityScanService(List<CrossExchangeMarketDataProvider> p,CrossExchangeOpportunitySelector s,CrossExchangeOpportunityStabilityGate g,CrossExchangeOpportunitySelector.Limits l,Map<Exchange,ExchangeCost> c,BigDecimal n,ExchangeHealthRegistry h,PerpetualContractCatalog catalog){providers=List.copyOf(p);selector=s;gate=g;limits=l;costs=c;targetNotional=n;health=h;this.catalog=catalog;}
 public List<CrossExchangeOpportunity> scan(String symbol,Instant now){if(catalog!=null)catalog.ensureInitialized(now);List<NormalizedFundingRateSnapshot> rates=new ArrayList<>();Map<Exchange,NormalizedOrderBookSnapshot> books=new EnumMap<>(Exchange.class);for(var p:providers){if(catalog!=null&&catalog.find(p.exchange(),symbol).isEmpty())continue;Instant requestStarted=Instant.now();try{NormalizedFundingRateSnapshot rate=p.fundingRate(symbol);NormalizedOrderBookSnapshot book=p.orderBook(symbol,20);Instant completedAt=Instant.now();long latencyMs=Duration.between(requestStarted,completedAt).toMillis();if(Duration.ofMillis(latencyMs).compareTo(limits.maxQuoteAge())>0)throw new IllegalStateException("market data request exceeded latency limit");rates.add(rate);books.put(p.exchange(),book);health.success(p.exchange(),now,latencyMs);}catch(RuntimeException e){health.failure(p.exchange(),now,e,Duration.between(requestStarted,Instant.now()).toMillis());}}List<CrossExchangeOpportunity> evaluated=new ArrayList<>();List<CrossExchangeOpportunity> stable=new ArrayList<>();for(var o:selector.evaluate(rates,books,costs,targetNotional,limits,now)){String id=stableId(o,now);CrossExchangeOpportunity item=new CrossExchangeOpportunity(id,o.symbol(),o.longQuote(),o.shortQuote(),o.hourlyFundingSpread(),o.estimatedNetYield(),o.executableNotional(),o.firstLegExchange(),o.status(),o.rejectionReason(),o.discoveredAt());if(gate.stable(item,now)){item=new CrossExchangeOpportunity(id,item.symbol(),item.longQuote(),item.shortQuote(),item.hourlyFundingSpread(),item.estimatedNetYield(),item.executableNotional(),item.firstLegExchange(),CrossExchangeOpportunity.Status.APPROVED,null,item.discoveredAt());approved.put(id,item);stable.add(item);}evaluated.add(item);}lastEvaluated=List.copyOf(evaluated);approved.entrySet().removeIf(entry->entry.getValue().longQuote().isStale(now,limits.maxQuoteAge())||entry.getValue().shortQuote().isStale(now,limits.maxQuoteAge()));return stable;}
 private String stableId(CrossExchangeOpportunity opportunity,Instant now){String raw=opportunity.symbol()+":"+opportunity.longQuote().exchange()+":"+opportunity.shortQuote().exchange()+":"+(now.toEpochMilli()/180000);return UUID.nameUUIDFromBytes(raw.getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();}
 public List<CrossExchangeOpportunity> lastEvaluated(){return lastEvaluated;}
 public Optional<CrossExchangeOpportunity> approvedOpportunity(String opportunityId,Instant now){CrossExchangeOpportunity opportunity=approved.get(opportunityId);if(opportunity==null)return Optional.empty();if(opportunity.longQuote().isStale(now,limits.maxQuoteAge())||opportunity.shortQuote().isStale(now,limits.maxQuoteAge())){approved.remove(opportunityId);return Optional.empty();}return Optional.of(opportunity);}
 public Set<String> commonSymbols(){Instant now=Instant.now();if(catalog!=null){catalog.ensureInitialized(now);Map<String,Integer>counts=new HashMap<>();catalog.snapshot().values().forEach(exchangeContracts->exchangeContracts.keySet().forEach(symbol->counts.merge(symbol,1,Integer::sum)));Set<String>result=new HashSet<>();counts.forEach((symbol,count)->{if(count>=2)result.add(symbol);});return Set.copyOf(result);}Map<String,Integer> counts=new HashMap<>();for(var p:providers){try{for(String s:new HashSet<>(p.supportedUsdtPerpetualSymbols()))counts.merge(s,1,Integer::sum);health.success(p.exchange(),now);}catch(RuntimeException e){health.failure(p.exchange(),now,e);}}Set<String> result=new HashSet<>();counts.forEach((s,n)->{if(n>=2)result.add(s);});return Set.copyOf(result);}
}
